# Find connected components of 1s (regions separated by 5s)
def find_regions(grid):
    height = len(grid)
    width = len(grid[0])

    visited = [[False]*width for _ in range(height)]
    regions = []
    current_region = []

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]:
                continue
            if grid[cr][cc] != 1:
                return False
            visited[cr][cc] = True
            current_region.append((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < height and 0 <= nc < width:
                    if not visited[nr][nc] and grid[nr][nc] == 1:
                        stack.append((nr, nc))
            return True

    for r in range(height):
        for c in range(width):
            if grid[r][c] == 1 and not visited[r][c]:
                success = dfs(r, c)
                if success:
                    regions.append(current_region)
                current_region = []

    return regions

