def is_enclosed(r, c, grid):
    # BFS/DFS from (r,c) - can we reach edge without crossing 5?
    visited = set()
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()
        if (cr, cc) in visited:
            continue
        visited.add((cr, cc))

        # Check if hit edge
        if cr == 0 or cr == height-1 or cc == 0 or cc == width-1:
            return False  # Reached edge

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < height and 0 <= nc < width:
                if grid[nr][nc] == 1 and (nr, nc) not in visited:
                    stack.append((nr, nc))

    return True

